function getDynamicBadge(zh, meaning, fallbackBadge) {
  const z = zh || '';
  const text = ` ${z} ${meaning || ''} `.toLowerCase();

  function matchAny(kws) {
    for (const kw of kws) {
      const regex = new RegExp('(?:^|[\\s,;:.?!/()\\[\\]{}\'\"-])' + kw + '(?=$|[\\s,;:.?!/()\\[\\]{}\'\"-])', 'i');
      if (regex.test(text)) return true;
    }
    return false;
  }

  const NUMERAL_CHARS = ['零', '一', '二', '两', '三', '四', '五', '六', '七', '八', '九', '十', '百', '千', '万', '亿', '半'];
  if (NUMERAL_CHARS.includes(z)) return '🔢 Số Từ & Số Đếm';
  if (z === '读书' || z === '看书') return '📖 Đọc Sách & Học Tập';
  if (z === '桃花') return '🌸 Hoa Đào & Thiên Nhiên';
  if (z === '桃树') return '🌳 Cây Đào & Tự Nhiên';
  if (z === '摘') return '🧺 Thu Hoạch Trái Cây';
  if (z === '结') return '🌱 Đơm Hoa Kết Trái';
  if (z === '五花肉') return '🥓 Thịt Ba Chỉ';
  if (z === '白菜') return '🥬 Cải Thảo';
  if (z === '鲜花') return '🌸 Hoa Tươi & Thiên Nhiên';
  if (z === '暴雨') return '⛈️ Mưa Bão & Thời Tiết';
  if (z === '自然') return '🌄 Thiên Nhiên & Môi Trường';

  const fruitWords = ['lê', 'đào', 'quýt', 'cam', 'táo', 'chuối', 'dưa', 'nho', 'dâu', 'chanh', 'xoài', 'hồng', 'bưởi', 'dừa', 'quả', 'trái', 'fruit', 'pear', 'peach', 'tangerine', 'mandarin', 'orange', 'apple', 'banana', 'melon', 'grape', 'berry', 'watermelon'];
  if (matchAny(fruitWords)) return '🍎 Hoa Quả & Trái Cây';

  const vegWords = ['rau', 'cải', 'cà chua', 'dưa chuột', 'dưa leo', 'khoai', 'cà rốt', 'hành', 'tỏi', 'gừng', 'ớt', 'nấm', 'ngô', 'bắp', 'vegetable', 'tomato', 'potato', 'cucumber', 'cabbage', 'carrot', 'onion', 'garlic', 'chili'];
  if (matchAny(vegWords)) return '🥦 Rau Củ & Nông Sản';

  const meatWords = ['thịt', 'sườn', 'bò', 'heo', 'lợn', 'gà', 'vịt', 'cừu', 'xúc xích', 'meat', 'beef', 'pork', 'chicken', 'duck', 'mutton', 'lamb', 'ribs', 'sausage'];
  if (matchAny(meatWords)) return '🥩 Thịt & Món Mặn';

  const seafoodWords = ['cá', 'tôm', 'cua', 'mực', 'sò', 'hàu', 'hải sản', 'fish', 'shrimp', 'crab', 'seafood', 'squid', 'lobster'];
  if (matchAny(seafoodWords)) return '🦐 Hải Sản Tươi Sống';

  const drinkWords = ['trà', 'cà phê', 'sữa', 'bia', 'rượu', 'nước', 'tea', 'coffee', 'milk', 'beer', 'wine', 'juice', 'water', 'drink'];
  if (matchAny(drinkWords)) return '☕ Đồ Uống & Trà';

  return fallbackBadge || '🍜 Ẩm Thực & Sinh Hoạt';
}


